#!/usr/bin/env node

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  createTemplateReport,
  validateReport,
} from './verify-pms-ai-rag-runtime-report.mjs';

const REPORT_FILE_NAME = 'pms-ai-rag-provider-ready-runtime-report.template.json';
const SUMMARY_FILE_NAME = 'pms-ai-rag-provider-ready-runtime-summary.md';
const REQUIRED_INPUTS_FILE_NAME = 'pms-ai-rag-provider-ready-required-inputs.json';
const REQUIRED_INPUTS_MD_FILE_NAME = 'pms-ai-rag-provider-ready-required-inputs.md';
const ENV_FILE_NAME = 'pms-ai-rag-provider-ready.env.template';
const README_FILE_NAME = 'README.md';
const MANIFEST_FILE_NAME = 'manifest.json';

const REQUIRED_INPUTS = [
  {
    id: 'pms-ai-rag-provider-env',
    kind: 'environment',
    required: [
      'AZURE_OPENAI_ENDPOINT',
      'AZURE_OPENAI_EMBEDDING_DEPLOYMENT',
      'AZURE_OPENAI_API_KEY or Entra credential or explicit AZURE_USE_MANAGED_IDENTITY=true',
    ],
    completionCheckId: 'pms-ai-rag-provider-ready-env',
    verificationCommand: 'pnpm run verify:pms-ai-rag-runtime:ready-precheck',
    description: 'Azure OpenAI embedding provider configuration used by the common AI/RAG runtime.',
  },
  {
    id: 'pms-ai-rag-provider-ready-runtime-report',
    kind: 'report',
    required: [
      'providerMode=ready',
      'project/task/projectMember/projectStatus source status, backfill, job run, retrieval, database audit, and embedding evidence',
    ],
    completionCheckId: 'pms-ai-rag-provider-ready-runtime-report',
    verificationCommand: 'pnpm run verify:pms-ai-rag-runtime-report -- --path=<report.json> --summary-path=<summary.md>',
    description: 'Passed PMS provider-ready runtime evidence JSON report generated from a real Azure-backed PMS runtime.',
  },
  {
    id: 'pms-ai-rag-provider-ready-summary',
    kind: 'summary',
    required: [
      'Markdown summary generated by verify:pms-ai-rag-runtime-report from the passed JSON report',
    ],
    completionCheckId: 'pms-ai-rag-provider-ready-summary',
    verificationCommand: 'pnpm run verify:pms-ai-rag-runtime-report -- --path=<report.json> --summary-path=<summary.md>',
    description: 'Human-readable Markdown summary bound to the verified PMS provider-ready JSON report.',
  },
  {
    id: 'pms-ai-rag-provider-ready-evidence-recording',
    kind: 'docs-evidence',
    required: [
      'Digest-bound evidence block recorded to PMS roadmap, backlog, and current baseline close brief',
    ],
    completionCheckId: 'pms-ai-rag-provider-ready-evidence-recording',
    verificationCommand: 'pnpm run complete:pms-ai-rag-provider-ready -- --use-existing-artifacts --report=<report.json> --summary=<summary.md>',
    description: 'Verified report and summary are recorded to PMS planning evidence markers after digest validation.',
  },
];

const argv = process.argv.slice(2);
const config = {
  help: argv.includes('--help'),
  selfTest: argv.includes('--self-test'),
  outDir: pickString(readOption('out-dir', 'PMS_AI_RAG_PROVIDER_READY_BUNDLE_DIR', 'output/pms-ai-rag-provider-ready')),
  baseUrl: pickString(readOption('base-url', 'PMS_AI_RAG_BASE_URL', 'http://127.0.0.1:4000/api')),
  workflowUrl: pickString(readOption('workflow-url', 'PMS_AI_RAG_PROVIDER_READY_WORKFLOW_URL', '')),
};

try {
  if (config.help) {
    printUsage();
    process.exit(0);
  }

  if (config.selfTest) {
    assertSelfTest();
    console.log('OK PMS AI/RAG provider-ready evidence bundle self-test passed');
    process.exit(0);
  }

  const bundle = prepareEvidenceBundle(config);
  console.log(`OK PMS AI/RAG provider-ready evidence bundle prepared: ${bundle.outDir}`);
  for (const file of bundle.files) {
    console.log(`- ${file.label}: ${file.path}`);
  }
} catch (error) {
  console.error(`FAIL PMS AI/RAG provider-ready evidence bundle preparation failed: ${formatError(error)}`);
  process.exit(1);
}

export function prepareEvidenceBundle(options) {
  const outDir = path.resolve(options.outDir);
  fs.mkdirSync(outDir, { recursive: true });

  const reportPath = path.join(outDir, REPORT_FILE_NAME);
  const summaryPath = path.join(outDir, SUMMARY_FILE_NAME);
  const requiredInputsPath = path.join(outDir, REQUIRED_INPUTS_FILE_NAME);
  const requiredInputsMarkdownPath = path.join(outDir, REQUIRED_INPUTS_MD_FILE_NAME);
  const envPath = path.join(outDir, ENV_FILE_NAME);
  const readmePath = path.join(outDir, README_FILE_NAME);
  const manifestPath = path.join(outDir, MANIFEST_FILE_NAME);

  const report = createTemplateReport();
  assertTemplateDraft(report);
  assertReportTemplateDoesNotPass(report);
  writeJson(reportPath, report);

  fs.writeFileSync(summaryPath, formatSummaryTemplate(reportPath), 'utf-8');
  const requiredInputs = formatRequiredInputs({
    rootDir: process.cwd(),
    baseUrl: options.baseUrl,
    workflowUrl: options.workflowUrl,
  });
  writeJson(requiredInputsPath, requiredInputs);
  fs.writeFileSync(requiredInputsMarkdownPath, formatRequiredInputsMarkdown(requiredInputs), 'utf-8');
  fs.writeFileSync(envPath, formatEnvTemplate({ outDir, baseUrl: options.baseUrl, reportPath, summaryPath }), 'utf-8');
  fs.writeFileSync(readmePath, formatReadme({
    outDir,
    baseUrl: options.baseUrl,
    reportPath,
    summaryPath,
    envPath,
    requiredInputsPath,
  }), 'utf-8');
  writeJson(manifestPath, formatManifest({
    outDir,
    reportPath,
    summaryPath,
    requiredInputsPath,
    requiredInputsMarkdownPath,
    envPath,
    readmePath,
  }));

  return {
    outDir,
    files: [
      { label: 'provider-ready-report-template', path: reportPath },
      { label: 'provider-ready-summary-template', path: summaryPath },
      { label: 'required-inputs-json', path: requiredInputsPath },
      { label: 'required-inputs-markdown', path: requiredInputsMarkdownPath },
      { label: 'env-template', path: envPath },
      { label: 'readme', path: readmePath },
      { label: 'manifest', path: manifestPath },
    ],
  };
}

function formatRequiredInputs(options) {
  return {
    schemaVersion: 1,
    status: 'request-only',
    generatedAt: new Date().toISOString(),
    rootDir: options.rootDir,
    baseUrl: options.baseUrl,
    workflowUrl: options.workflowUrl || '',
    providerEnv: getProviderEnvStatus(),
    requiredExternalInputs: REQUIRED_INPUTS.map((input) => ({
      ...input,
      status: input.id === 'pms-ai-rag-provider-env' && getProviderEnvStatus().ready ? 'available' : 'missing',
    })),
  };
}

function formatRequiredInputsMarkdown(packet) {
  const lines = [
    '# PMS AI/RAG Provider-Ready Required Inputs',
    '',
    'This request packet is not completion evidence. It lists the inputs still required before PMS AI/RAG provider-ready evidence can be recorded.',
    '',
    `- baseUrl: ${packet.baseUrl}`,
    `- providerEnvReady: ${packet.providerEnv.ready}`,
    `- providerCredentialMode: ${packet.providerEnv.credentialMode || '(missing)'}`,
    `- missing: ${packet.providerEnv.missing.join(' | ') || '(none)'}`,
    `- placeholders: ${packet.providerEnv.placeholders.join(' | ') || '(none)'}`,
    `- invalid: ${packet.providerEnv.invalid.join(' | ') || '(none)'}`,
    '',
    '## Required Inputs',
    '',
  ];

  for (const input of packet.requiredExternalInputs) {
    lines.push(`### ${input.id}`);
    lines.push('');
    lines.push(`- status: ${input.status}`);
    lines.push(`- kind: ${input.kind}`);
    lines.push(`- required: ${input.required.join(' | ')}`);
    lines.push(`- completionCheckId: ${input.completionCheckId}`);
    lines.push(`- verificationCommand: ${input.verificationCommand}`);
    lines.push(`- description: ${input.description}`);
    lines.push('');
  }

  return `${lines.join('\n')}`;
}

function formatEnvTemplate(options) {
  const evidenceBlockPath = path.join(options.outDir, 'pms-ai-rag-provider-ready-evidence.md');
  return [
    '# PMS AI/RAG provider-ready evidence env template',
    '# Replace empty/provider values before running complete:pms-ai-rag-provider-ready.',
    '',
    `PMS_AI_RAG_BASE_URL=${options.baseUrl}`,
    `PMS_AI_RAG_PROVIDER_READY_REPORT_PATH=${options.reportPath}`,
    `PMS_AI_RAG_PROVIDER_READY_SUMMARY_PATH=${options.summaryPath}`,
    `PMS_AI_RAG_PROVIDER_READY_EVIDENCE_BLOCK_PATH=${evidenceBlockPath}`,
    'PMS_AI_RAG_PROVIDER_READY_ROADMAP_PATH=docs/pms/planning/roadmap.md',
    'PMS_AI_RAG_PROVIDER_READY_BACKLOG_PATH=docs/pms/planning/backlog.md',
    'PMS_AI_RAG_PROVIDER_READY_CLOSE_BRIEF_PATH=docs/pms/planning/current-baseline-close-brief.md',
    '',
    '# Azure OpenAI embedding provider environment.',
    'AZURE_OPENAI_ENDPOINT=',
    'AZURE_OPENAI_EMBEDDING_DEPLOYMENT=',
    '# Use one credential mode: API key, Entra service principal, or managed identity.',
    'AZURE_OPENAI_API_KEY=',
    '# AZURE_TENANT_ID=',
    '# AZURE_CLIENT_ID=',
    '# AZURE_CLIENT_SECRET=',
    '# AZURE_USE_MANAGED_IDENTITY=true',
    '',
  ].join('\n');
}

function formatReadme(options) {
  return [
    '# PMS AI/RAG Provider-Ready Evidence Bundle',
    '',
    'This directory contains draft authoring templates only. It is not provider-ready completion evidence until every draft value is replaced by a real Azure-backed PMS runtime run and each verifier passes.',
    '',
    '## Files',
    '',
    `- \`${REPORT_FILE_NAME}\`: draft JSON shape for project/task/projectMember/projectStatus provider-ready runtime evidence.`,
    `- \`${SUMMARY_FILE_NAME}\`: placeholder summary path. The real summary is generated by the report verifier.`,
    `- \`${REQUIRED_INPUTS_FILE_NAME}\`: request-only list of missing provider-ready inputs.`,
    `- \`${REQUIRED_INPUTS_MD_FILE_NAME}\`: human-readable request packet for the same inputs.`,
    `- \`${ENV_FILE_NAME}\`: environment variables for the completion runner.`,
    '- `manifest.json`: generated file index and commands.',
    '',
    '## Verification Flow',
    '',
    '1. Fill the Azure OpenAI provider values in the env template.',
    '2. Run the provider-ready precheck:',
    '',
    `   pnpm run verify:pms-ai-rag-runtime:ready-precheck -- --base-url=${options.baseUrl}`,
    '',
    '3. Generate live PMS provider-ready evidence and verify it in one ordered flow:',
    '',
    `   pnpm run complete:pms-ai-rag-provider-ready -- --env-file=${options.envPath} --base-url=${options.baseUrl} --dry-run`,
    '',
    '   Remove `--dry-run` only after the generated report and summary are reviewed.',
    '',
    '4. If you already have a live report and summary, replay the verification and recording path:',
    '',
    `   pnpm run complete:pms-ai-rag-provider-ready -- --use-existing-artifacts --report=${options.reportPath} --summary=${options.summaryPath} --dry-run`,
    '',
    '5. Verify the final assembled bundle after the draft report has been replaced with a passed report:',
    '',
    `   pnpm run verify:pms-ai-rag-provider-ready-bundle -- --bundle-dir=${options.outDir}`,
    '',
    'A draft report must fail the final bundle verifier. That failure is intentional and prevents template files from being mistaken for launch evidence.',
    '',
  ].join('\n');
}

function formatManifest(options) {
  return {
    schemaVersion: 1,
    status: 'draft',
    generatedAt: new Date().toISOString(),
    bundleDir: options.outDir,
    envTemplatePath: options.envPath,
    readmePath: options.readmePath,
    requiredExternalInputs: {
      status: 'request-only',
      jsonPath: options.requiredInputsPath,
      markdownPath: options.requiredInputsMarkdownPath,
      count: REQUIRED_INPUTS.length,
    },
    reports: [
      {
        id: 'pms-ai-rag-provider-ready-runtime',
        description: 'Azure-backed PMS AI/RAG provider-ready runtime report for project/task/projectMember/projectStatus.',
        templatePath: options.reportPath,
        summaryPath: options.summaryPath,
        envName: 'PMS_AI_RAG_PROVIDER_READY_REPORT_PATH',
        verifyScript: 'verify:pms-ai-rag-runtime-report',
        verifyCommand: `pnpm run verify:pms-ai-rag-runtime-report -- --path=${options.reportPath} --summary-path=${options.summaryPath}`,
      },
    ],
    completionFlow: {
      script: 'complete:pms-ai-rag-provider-ready',
      command: `pnpm run complete:pms-ai-rag-provider-ready -- --env-file=${options.envPath}`,
      recordsEvidenceAfterVerification: true,
    },
  };
}

function formatSummaryTemplate(reportPath) {
  return [
    '# PMS AI/RAG Provider-Ready Runtime Evidence',
    '',
    'Draft placeholder. Generate the real summary with:',
    '',
    `pnpm run verify:pms-ai-rag-runtime-report -- --path=${reportPath} --summary-path=${SUMMARY_FILE_NAME}`,
    '',
  ].join('\n');
}

function assertTemplateDraft(report) {
  if (report?.schemaVersion !== 1 || report?.status !== 'draft') {
    throw new Error('PMS provider-ready report template must use schemaVersion 1 and status draft.');
  }
}

function assertReportTemplateDoesNotPass(report) {
  try {
    validateReport(report);
  } catch {
    return;
  }
  throw new Error('PMS provider-ready report template unexpectedly passed verifier.');
}

function getProviderEnvStatus() {
  const endpoint = pickString(process.env.AZURE_OPENAI_ENDPOINT);
  const embeddingDeployment = pickString(process.env.AZURE_OPENAI_EMBEDDING_DEPLOYMENT);
  const apiKey = pickString(process.env.AZURE_OPENAI_API_KEY);
  const entra = Boolean(
    pickString(process.env.AZURE_TENANT_ID)
      && pickString(process.env.AZURE_CLIENT_ID)
      && pickString(process.env.AZURE_CLIENT_SECRET),
  );
  const managedIdentity = readOptionalBooleanEnv('AZURE_USE_MANAGED_IDENTITY');
  const missing = [];
  const placeholders = [];
  const invalid = [];

  if (!endpoint) {
    missing.push('AZURE_OPENAI_ENDPOINT');
  } else if (isPlaceholder(endpoint)) {
    placeholders.push('AZURE_OPENAI_ENDPOINT');
  }
  if (!embeddingDeployment) {
    missing.push('AZURE_OPENAI_EMBEDDING_DEPLOYMENT');
  } else if (isPlaceholder(embeddingDeployment)) {
    placeholders.push('AZURE_OPENAI_EMBEDDING_DEPLOYMENT');
  }
  if (managedIdentity === null && pickString(process.env.AZURE_USE_MANAGED_IDENTITY)) {
    invalid.push('AZURE_USE_MANAGED_IDENTITY must be true or false');
  }
  if (apiKey && looksLikeJwt(apiKey)) {
    invalid.push('AZURE_OPENAI_API_KEY looks like an Entra JWT token');
  }
  if (!apiKey && !entra && managedIdentity !== true) {
    missing.push('AZURE_OPENAI_API_KEY or Entra credential or explicit AZURE_USE_MANAGED_IDENTITY=true');
  } else if (apiKey && isPlaceholder(apiKey)) {
    placeholders.push('AZURE_OPENAI_API_KEY');
  }

  const credentialMode = apiKey ? 'api-key' : entra ? 'entra-service-principal' : managedIdentity === true ? 'managed-identity' : '';
  return {
    ready: missing.length === 0 && placeholders.length === 0 && invalid.length === 0,
    credentialMode,
    missing,
    placeholders,
    invalid,
  };
}

function assertSelfTest() {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssoo-pms-ai-rag-provider-ready-bundle-'));
  try {
    const bundle = prepareEvidenceBundle({
      outDir: path.join(tempDir, 'bundle'),
      baseUrl: 'http://127.0.0.1:4000/api',
      workflowUrl: 'https://example.invalid/actions/runs/pms-ai-rag',
    });

    for (const file of bundle.files) {
      assertFileExists(file.path);
    }

    const manifest = readJson(path.join(bundle.outDir, MANIFEST_FILE_NAME), 'manifest');
    if (manifest.status !== 'draft' || !Array.isArray(manifest.reports) || manifest.reports.length !== 1) {
      throw new Error('self-test manifest must be draft and include one PMS AI/RAG report.');
    }
    if (manifest.requiredExternalInputs?.status !== 'request-only') {
      throw new Error('self-test manifest must mark required inputs as request-only.');
    }

    const requiredInputs = readJson(path.join(bundle.outDir, REQUIRED_INPUTS_FILE_NAME), 'required inputs');
    if (!requiredInputs.requiredExternalInputs?.some((item) => item.id === 'pms-ai-rag-provider-env')) {
      throw new Error('self-test required inputs must include provider env request.');
    }

    const readme = fs.readFileSync(path.join(bundle.outDir, README_FILE_NAME), 'utf-8');
    assertIncludes(readme, 'complete:pms-ai-rag-provider-ready', 'self-test README completion runner');
    assertIncludes(readme, 'verify:pms-ai-rag-provider-ready-bundle', 'self-test README bundle verifier');
    assertIncludes(readme, 'draft report must fail', 'self-test README draft warning');

    const report = readJson(path.join(bundle.outDir, REPORT_FILE_NAME), 'report template');
    assertTemplateDraft(report);
    assertReportTemplateDoesNotPass(report);
  } finally {
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
}

function writeJson(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`, 'utf-8');
}

function readJson(filePath, label) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
  } catch (error) {
    throw new Error(`Failed to read ${label} at ${filePath}: ${formatError(error)}`);
  }
}

function assertFileExists(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Missing expected bundle file: ${filePath}`);
  }
}

function assertIncludes(value, pattern, label) {
  if (!value.includes(pattern)) {
    throw new Error(`${label} must include ${pattern}.`);
  }
}

function pickString(value) {
  const trimmed = value?.trim();
  return trimmed ? trimmed : undefined;
}

function readOption(name, envName, fallback) {
  const prefix = `--${name}=`;
  const inline = argv.find((value) => value.startsWith(prefix));
  if (inline) {
    return inline.slice(prefix.length);
  }
  const index = argv.indexOf(`--${name}`);
  if (index !== -1 && argv[index + 1]) {
    return argv[index + 1];
  }
  return process.env[envName] ?? fallback;
}

function readOptionalBooleanEnv(name) {
  const value = pickString(process.env[name]);
  if (!value) {
    return undefined;
  }
  if (value.toLowerCase() === 'true') {
    return true;
  }
  if (value.toLowerCase() === 'false') {
    return false;
  }
  return null;
}

function isPlaceholder(value) {
  return /change-me|example|placeholder|your-/i.test(value);
}

function looksLikeJwt(value) {
  return /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(value);
}

function formatError(error) {
  return error instanceof Error ? error.message : String(error);
}

function printUsage() {
  console.log(`
Usage:
  pnpm run prepare:pms-ai-rag-provider-ready-bundle -- [options]

Options:
  --out-dir=<dir>       Output directory for the PMS provider-ready evidence bundle
  --base-url=<url>      PMS API base URL used by the completion runner
  --workflow-url=<url>  Optional CI/workflow URL to carry into the request packet
  --self-test           Run local bundle generation self-test

Environment:
  PMS_AI_RAG_PROVIDER_READY_BUNDLE_DIR
  PMS_AI_RAG_BASE_URL
  PMS_AI_RAG_PROVIDER_READY_WORKFLOW_URL
`);
}
